function updateProgress(){const main=pageEntries('main');const done=main.filter(e=>state[e.id]).length;const p=main.length?Math.round(done/main.length*100):0;$('#progressText').textContent=`${done} / ${main.length}`;$('#progressPct').textContent=p+'%';$('#progressBar').style.width=p+'%';}
function card(e){const sp=spritePath(e),poke=isPokeApiOverride(e),col=!!state[e.id],fav=!!favorites[e.id],match=window.searchMatches?.has(e.id);return `<article class="card ${col?'collected':''} ${fav?'favorite-card':''} ${match?'search-match':''}" data-real-id="${esc(e.id)}"><div class="card-main"><div class="num">#${String(e.dex).padStart(3,'0')}</div><div class="card-actions"><button class="fav-toggle ${fav?'fav':''}" aria-label="${fav?'Remove favorite':'Add favorite'}" title="${fav?'Remove favorite':'Add favorite'}"><span class="action-heart" aria-hidden="true">♡</span></button><button class="collect-toggle ${col?'collected':''}" aria-label="${col?'Mark not caught':'Mark caught'}" title="${col?'Mark not caught':'Mark caught'}"><span class="action-pokeball" aria-hidden="true"></span></button></div><div class="sprite ${poke?'pokeapi':''}"><img loading="lazy" src="${sp}" alt="${esc(e.name)}"></div></div><div class="card-footer"><div class="name">${esc(e.name)}</div><div class="types">${entryTypes(e).map(t=>`<span class="type" style="${typeStyle(t)}">${esc(typeLabel(t))}</span>`).join('')}</div></div></article>`;}
