  $('#empty').hidden=!!slice.length;
  $('#pageInfo').textContent=`Page ${page} / ${max}`;
  $('#prev').disabled=page<=1;$('#next').disabled=page>=max;
  const boxes=[...new Set(slice.map(e=>e.box).filter(Boolean))];
  $('#boxHeading').textContent=['kanto','johto','hoenn','sinnoh','unova','kalos','alola','galar','paldea'].includes(tab)?`Page ${page}`:(['main'].includes(tab)?`Box ${boxes.length===1?boxes[0]:(slice[0]?.box||page)}`:`Page ${page}`);
