function attachCardEvents(){$$('.card').forEach(c=>{c.onclick=e=>{if(e.target.closest('.collect-toggle,.fav-toggle'))return;openInfo(c.dataset.realId);};c.querySelector('.collect-toggle').onclick=e=>{e.stopPropagation();const id=c.dataset.realId;const active=!state[id];state[id]=active;if(!active)delete state[id];saveAll();render();requestAnimationFrame(()=>{const n=document.querySelector(`.card[data-real-id=\"${CSS.escape(id)}\"]`);if(n){n.classList.add('action-pop',active?'caught-pop':'uncaught-pop');setTimeout(()=>n.classList.remove('action-pop','caught-pop','uncaught-pop'),520);}});};c.querySelector('.fav-toggle').onclick=e=>{e.stopPropagation();const id=c.dataset.realId;const active=!favorites[id];favorites[id]=active;if(!active)delete favorites[id];saveAll();render();requestAnimationFrame(()=>{const n=document.querySelector(`.card[data-real-id=\"${CSS.escape(id)}\"]`);if(n){n.classList.add('action-pop',active?'favorite-pop':'unfavorite-pop');setTimeout(()=>n.classList.remove('action-pop','favorite-pop','unfavorite-pop'),520);}});};});}
function loadTypes(){render();}
function renderTypeModal(){$('#typeOptions').innerHTML=TYPES.map(t=>`<button class="type-option ${selectedTypes.includes(t)?'selected':''}" data-type="${t}" style="${typeStyle(t)}">${esc(typeLabel(t))}</button>`).join('');$$('.type-option').forEach(b=>b.onclick=()=>{const t=b.dataset.type;selectedTypes=selectedTypes.includes(t)?selectedTypes.filter(x=>x!==t):[...selectedTypes,t];page=1;render();renderTypeModal();});}
function speciesForEntry(e){const sp=LOCAL_SPECIES[speciesKeyFromName(e.raw||e.name||'')]||speciesByDex[Number(e.dex)];if(!sp)return null;const formName=String(e.form||'');if(!formName)return sp;const normForm=norm(formName).replace(/[^a-z0-9]+/g,'');let f=(sp.forms||[]).find(x=>norm(x.name).replace(/[^a-z0-9]+/g,'')===normForm);if(!f&&/alola/i.test(formName))f=(sp.forms||[]).find(x=>/alola/i.test(x.name));if(!f&&/hisu/i.test(formName))f=(sp.forms||[]).find(x=>/hisu/i.test(x.name));if(!f&&/galar/i.test(formName))f=(sp.forms||[]).find(x=>/galar/i.test(x.name));return f?{...sp,...f,name:sp.name,form:f.name}:sp;}
function localSpawn(e){const sp=speciesForEntry(e);if(!sp)return[];const names=[sp.name,e.raw,e.name].filter(Boolean).map(norm);let out=[];for(const n of names)out.push(...(SPAWN_BY_POKEMON[n]||[]));return out.filter((x,i,a)=>x.enabled!==false&&x.type==='pokemon'&&a.findIndex(y=>y.id===x.id)===i);}
function prettyLabel(s){return String(s??'').replace(/^#/,'').replace(/^cobblemon:/,'').replace(/^minecraft:/,'').replace(/_/g,' ').replace(/-/g,' ').replace(/\b\w/g,m=>m.toUpperCase());}
function formatCondition(c){if(!c)return[];const l=[];if(c.biomes?.length)l.push(`Biomes: ${c.biomes.map(prettyLabel).join(', ')}`);if(c.neededBaseBlocks?.length)l.push(`Blocks: ${c.neededBaseBlocks.map(prettyLabel).join(', ')}`);if(c.neededNearbyBlocks?.length)l.push(`Nearby: ${c.neededNearbyBlocks.map(prettyLabel).join(', ')}`);if(c.dimensions?.length)l.push(`Dimensions: ${c.dimensions.map(prettyLabel).join(', ')}`);if(c.timeRange)l.push(`Time: ${c.timeRange}`);if(c.minY!=null||c.maxY!=null)l.push(`Y: ${c.minY??'-∞'} – ${c.maxY??'∞'}`);if(c.minLight!=null||c.maxLight!=null)l.push(`Light: ${c.minLight??0}–${c.maxLight??15}`);if(c.minSkyLight!=null||c.maxSkyLight!=null)l.push(`Skylight: ${c.minSkyLight??0}–${c.maxSkyLight??15}`);if(c.canSeeSky!=null)l.push(`Sky: ${c.canSeeSky?'yes':'no'}`);if(c.isRaining!=null)l.push(`Rain: ${c.isRaining?'yes':'no'}`);if(c.isThundering!=null)l.push(`Thunder: ${c.isThundering?'yes':'no'}`);return l;}
function spawnCard(s){const c=formatCondition(s.condition),a=formatCondition(s.anticondition);return `<div class="spawn-card"><div class="spawn-top"><span class="spawn-bucket">${esc(prettyLabel(s.bucket||'Spawn'))}</span><span>${esc(T('level'))} ${esc(s.level||'?')}</span></div><div class="chips">${[s.spawnablePositionType,...(s.presets||[])].filter(Boolean).map(x=>`<span class="chip">${esc(prettyLabel(x))}</span>`).join('')}</div>${s.weight!=null?`<div class="spawn-line">Weight: <b>${esc(s.weight)}</b></div>`:''}${c.length?`<div class="spawn-line"><b>Conditions</b><br>${c.map(esc).join('<br>')}</div>`:''}${a.length?`<div class="spawn-line"><b>Exclusions</b><br>${a.map(esc).join('<br>')}</div>`:''}</div>`;}
const evoReverse={};for(const[k,sp]of Object.entries(LOCAL_SPECIES)){for(const ev of sp.evolutions||[]){const r=speciesKeyFromName(ev.result||'');if(r)(evoReverse[r]??=[]).push(k);}for(const f of sp.forms||[])for(const ev of f.evolutions||[]){const r=speciesKeyFromName(ev.result||'');if(r)(evoReverse[r]??=[]).push(k);}}
function evoRequirement(ev){const out=[];if(ev.requiredContext)out.push(`Item: ${prettyLabel(String(ev.requiredContext).split(':').pop())}`);for(const r of(ev.requirements||[])){const v=r.variant;if(v==='level')out.push(`Level ${r.minLevel??''}${r.maxLevel!=null?`–${r.maxLevel}`:''}`);else if(v==='friendship')out.push(`Friendship ≥ ${r.amount??r.minFriendship??'?'} `);else if(v==='item')out.push(`Item: ${prettyLabel(r.item||r.itemName||'')}`);else if(v==='held_item')out.push(`Held item: ${prettyLabel(r.heldItem||r.item||'')}`);else if(v==='move')out.push(`Move: ${prettyLabel(r.move||'')}`);else if(v==='time')out.push(`Time: ${prettyLabel(r.time||'')}`);else if(v==='biome'){const bm={'#cobblemon:evolution/regional/pikachu_alolabiome':'Beach / Tropical Island','#cobblemon:evolution/regional/pikachu_kantobiome':'Forest','#cobblemon:evolution/regional/cubone_alolabiome':'Beach / Tropical Island','#cobblemon:evolution/regional/exeggcute_alolabiome':'Beach / Tropical Island'};if(r.biomeCondition)out.push(`Biome: ${bm[r.biomeCondition]||prettyLabel(r.biomeCondition)}`);if(r.biomeAnticondition)out.push(`Not biome: ${bm[r.biomeAnticondition]||prettyLabel(r.biomeAnticondition)}`);}else{const vals=Object.entries(r).filter(([k])=>k!=='variant').map(([k,v])=>`${prettyLabel(k)}: ${prettyLabel(String(v))}`);if(vals.length)out.push(vals.join(', '));}}return out.join(' + ')||prettyLabel(ev.variant||'');}
function findEntryForEvolution(result,source){const rawText=norm(result);let formHint='';if(/\balolan\b/.test(rawText))formHint='alola';else if(/\bhisuian\b/.test(rawText))formHint='hisui';else if(/\bgalarian\b/.test(rawText))formHint='galar';else if(/\bpaldean\b/.test(rawText))formHint='paldea';const baseText=rawText.replace(/\b(alolan|hisuian|galarian|paldean)\b/g,'').trim();const baseNorm=baseText.replace(/[^a-z0-9]+/g,'');let candidates=entries.filter(e=>{const er=norm(e.raw||e.name).replace(/[^a-z0-9]+/g,'');const en=norm(e.name).replace(/[^a-z0-9]+/g,'');return er===baseNorm||en===baseNorm||er===baseNorm+formHint||en===formHint+baseNorm;});if(formHint)candidates=candidates.filter(e=>norm(`${e.form} ${e.name}`).includes(formHint)||norm(e.raw).includes(formHint));else candidates=candidates.filter(e=>!e.form);return candidates[0]||entries.find(e=>Number(e.dex)===Number(source?.dex)&&!e.form)||null;}
function evoBranchesFor(e){
  const sp=speciesForEntry(e);
  if(!sp)return [];
  const targetKey=speciesKeyFromName(e.raw||e.name||'');
  if(!targetKey)return [];
  const roots=[];const seenAnc=new Set();
  function rootsFor(key){if(seenAnc.has(key))return;seenAnc.add(key);const parents=[...(evoReverse[key]||[])].filter(Boolean);if(!parents.length){roots.push(key);return;}parents.forEach(rootsFor);}
  rootsFor(targetKey);
  const entryForKey=key=>entries.find(x=>!x.form&&speciesKeyFromName(x.raw||x.name||'')===key)||entries.find(x=>speciesKeyFromName(x.raw||x.name||'')===key)||null;
  const branches=[];
  function walk(node,path,seen){
    const key=speciesKeyFromName(node.entry?.raw||node.entry?.name||node.species?.name||'')||String(node.entry?.id||'');
    if(seen.has(key))return;
    const nextSeen=new Set(seen);nextSeen.add(key);
    const here=[...path,node];const next=[];
    for(const ev of node.species?.evolutions||[]){
      const en=findEntryForEvolution(ev.result,node.entry);if(!en||en.id===node.entry?.id)continue;
      const ns=speciesForEntry(en);if(!ns)continue;
      const nk=speciesKeyFromName(en.raw||en.name||'')||String(en.id);if(nextSeen.has(nk))continue;
      next.push({entry:en,species:ns,from:ev});
    }
    if(!next.length){if(here.some(n=>n.entry?.id===e.id))branches.push(here);return;}
    next.forEach(n=>walk(n,here,nextSeen));
  }
  (roots.length?roots:[targetKey]).forEach(k=>{const re=entryForKey(k);if(re){const rs=speciesForEntry(re);if(rs)walk({entry:re,species:rs},[],new Set());}});
  return branches;
}
function evoHtml(e){const branches=evoBranchesFor(e);if(!branches.length)return `<div class="empty-panel">${esc(T('noEvolution'))}</div>`;return branches.map(br=>`<div class="evo-chain">${br.map((n,i)=>`${i?`<span class="evo-arrow">→<small>${esc(evoRequirement(n.from))}</small></span>`:''}<div class="evo-node"><img src="${spritePath(n.entry)}" alt="${esc(n.species.name)}"><b>${esc(n.species.name)}</b>${n.entry.form?`<small>${esc(n.entry.form)}</small>`:''}</div>`).join('')}</div>`).join('');}
function statHtml(sp){const labels=[['hp','HP'],['attack','Attack'],['defence','Defense'],['special_attack','Sp. Atk'],['special_defence','Sp. Def'],['speed','Speed']];return labels.map(([k,l])=>{const v=Number(sp.baseStats?.[k])||0;return `<div class="stat-row"><label>${l}</label><div class="stat-bar"><i style="width:${Math.min(100,v/2)}%"></i></div><span>${v}</span></div>`}).join('');}
function infoHeader(e,sp){const[n,form]=nameParts(e);return `<div class="info-head"><img class="${isPokeApiOverride(e)?'pokeapi-info':''}" src="${spritePath(e)}"><div><div class="dex">#${String(e.dex).padStart(3,'0')}</div><h2>${esc(n)}</h2>${form?`<div class="sub">${esc(form)}</div>`:''}<div class="info-types">${entryTypes(e).map(t=>`<span class="type" style="${typeStyle(t)}">${esc(typeLabel(t))}</span>`).join('')}</div></div></div>`;}
function renderInfo(e,sp){const spawn=localSpawn(e);const inTeam=team.includes(e.id);return `${infoHeader(e,sp)}<div class="info-section"><h3>${T('basic')}</h3><div class="info-grid"><div class="info-item"><b>Abilities</b><span>${esc((sp.abilities||[]).join(', ')||'—')}</span></div><div class="info-item"><b>${T('height')}</b><span>${sp.height!=null?(Number(sp.height)/10).toFixed(1)+' m':'—'}</span></div><div class="info-item"><b>${T('weight')}</b><span>${sp.weight!=null?(Number(sp.weight)/10).toFixed(1)+' kg':'—'}</span></div><div class="info-item"><b>Base Experience</b><span>${sp.baseExperienceYield??'—'}</span></div><div class="info-item"><b>Catch rate</b><span>${sp.catchRate??'—'}</span></div></div><div class="info-actions"><button id="infoTeamBtn" class="primary">${inTeam?T('removeTeam'):T('addTeam')}</button><button id="infoFavBtn" class="secondary">${favorites[e.id]?'★':'☆'} ${T('favorite')}</button></div></div><div class="info-section"><h3>${T('evolution')}</h3>${evoHtml(e)}</div><div class="info-tabs"><button class="info-tab active" data-panel="stats">${T('stats')}</button><button class="info-tab" data-panel="spawn">${T('spawnInfo')}</button><button class="info-tab" data-panel="breeding">${T('breeding')}</button><button class="info-tab" data-panel="notes">${T('notes')}</button></div><div class="info-panel active" data-panel-content="stats">${statHtml(sp)}</div><div class="info-panel" data-panel-content="spawn">${spawn.length?spawn.map(spawnCard).join(''):`<div class="empty-panel">${T('noSpawn')}</div>`}</div><div class="info-panel" data-panel-content="breeding"><div class="info-grid"><div class="info-item"><b>Egg groups</b><span>${esc((sp.eggGroups||[]).map(prettyLabel).join(', ')||'—')}</span></div><div class="info-item"><b>Experience group</b><span>${esc(prettyLabel(sp.experienceGroup||'')||'—')}</span></div><div class="info-item"><b>Base friendship</b><span>${sp.baseFriendship??'—'}</span></div></div></div><div class="info-panel" data-panel-content="notes"><textarea id="pokemonNote" class="note-box" placeholder="${language==='nl'?'Schrijf hier je eigen notitie...':'Write your own note...'}">${esc(notes[e.id]||'')}</textarea><button id="saveNote" class="primary note-save">Opslaan</button></div><div class="info-source">Cobblemon 1.7.3 · ${T('localData')}</div>`;}
function openInfo(id){const e=entries.find(x=>x.id===id);if(!e)return;const sp=speciesForEntry(e);$('#infoContent').innerHTML=sp?renderInfo(e,sp):`<div class="info-error">${T('noInfo')}</div>`;$('#infoOverlay').hidden=false;$('#infoDropdown').hidden=false;document.body.classList.add('modal-open');$('#infoDropdown').scrollTop=0;bindInfoTabs();$('#infoTeamBtn')?.addEventListener('click',()=>{if(toggleTeam(e.id))openInfo(e.id);else openInfo(e.id);});$('#infoFavBtn')?.addEventListener('click',()=>{favorites[e.id]=!favorites[e.id];if(!favorites[e.id])delete favorites[e.id];saveAll();openInfo(e.id);});$('#saveNote')?.addEventListener('click',()=>{notes[e.id]=$('#pokemonNote').value;saveAll();$('#saveNote').textContent=language==='nl'?'Opgeslagen ✓':'Saved ✓';});}
function bindInfoTabs(){$$('.info-tab').forEach(b=>b.onclick=()=>{$$('.info-tab').forEach(x=>x.classList.toggle('active',x===b));$$('[data-panel-content]').forEach(p=>p.classList.toggle('active',p.dataset.panelContent===b.dataset.panel));$('#infoDropdown').scrollTop=0;});}
function closeInfo(){$('#infoDropdown').hidden=true;$('#infoOverlay').hidden=true;document.body.classList.remove('modal-open');}
function toggleTeam(id){const i=team.indexOf(id);if(i>=0){team.splice(i,1);saveAll();return true;}if(team.length>=6){alert(language==='nl'?'Je team zit al vol. Verwijder eerst een Pokémon voordat je een nieuwe toevoegt.':'Your team is already full. Remove a Pokémon before adding a new one.');return false;}team.push(id);saveAll();return true;}
function entryById(id){return entries.find(e=>e.id===id)||null;}
function teamTypes(){return team.map(entryById).filter(Boolean).map(entryTypes);}
function effectiveness(defTypes,atk){let m=1;for(const d of defTypes)m*=TYPE_CHART[atk]?.[d]??1;return m;}
function typeBucket(defTypes,mode){const out=[];for(const t of TYPES){const m=effectiveness(defTypes,t);if(mode==='weak'&&m>1)out.push([t,m]);if(mode==='resist'&&m>0&&m<1)out.push([t,m]);if(mode==='immune'&&m===0)out.push([t,m]);}return out;}
function teamAnalysis(){const arr=[];for(const atk of TYPES){let count=0,total=0,max=0;for(const e of team.map(entryById).filter(Boolean)){const m=effectiveness(entryTypes(e),atk);if(m>1)count++;if(m>1)max=Math.max(max,m);total+=m;}if(count)arr.push({type:atk,count,max,total});}return arr;}
function renderTeam(){const slots=Array.from({length:6},(_,i)=>team[i]?entryById(team[i]):null);const analysis=teamAnalysis();const distribution=TYPES.map(t=>({type:t,n:teamTypes().filter(a=>a.includes(t)).length})).filter(x=>x.n);const weaknessRows=analysis.sort((a,b)=>b.max-a.max||b.count-a.count).map(x=>`<div class="coverage-row"><span class="type" style="${typeStyle(x.type)}">${esc(typeLabel(x.type))}</span><span class="coverage-multiplier ${x.max>=4?'danger':''}">${x.max>=4?'4×':x.max>=2?'2×':'—'}</span><span class="coverage-count">${x.count} / ${team.length} weak</span></div>`).join('');$('#view').innerHTML=`<div class="page-card team-page"><div class="page-title team-title"><div><div class="eyebrow">BUILD • ANALYZE • PLAY</div><h2>${T('team')}</h2><p>Build a six-Pokémon team and instantly see its defensive type profile.</p></div><button id="clearTeam" class="secondary">Clear team</button></div><div class="team-grid">${slots.map((e,i)=>e?`<article class="team-slot filled"><button class="remove-team" data-id="${esc(e.id)}" aria-label="Remove ${esc(e.name)}">×</button><div class="team-number">${String(i+1).padStart(2,'0')}</div><img src="${spritePath(e)}" alt="${esc(e.name)}"><b>${esc(e.name)}</b><div class="types team-types">${entryTypes(e).map(t=>`<span class="type" style="${typeStyle(t)}">${esc(typeLabel(t))}</span>`).join('')}</div></article>`:`<button class="team-slot empty" data-slot="${i}"><span class="plus">+</span><b>Add Pokémon</b><small>Slot ${i+1}</small></button>`).join('')}</div><div class="team-dashboard"><section class="team-panel"><div class="panel-heading"><div><span class="eyebrow">DEFENSIVE PROFILE</span><h3>Type coverage</h3></div><span class="team-count">${team.length}/6</span></div>${team.length?`<div class="coverage-list">${weaknessRows||'<div class="empty-panel">No type weaknesses detected.</div>'}</div>`:'<div class="empty-panel">Add Pokémon to see your team analysis.</div>'}</section><section class="team-panel"><div class="panel-heading"><div><span class="eyebrow">TEAM MAKEUP</span><h3>Type distribution</h3></div></div><div class="distribution-grid">${distribution.length?distribution.map(x=>`<div class="distribution-item"><span class="type" style="${typeStyle(x.type)}">${esc(typeLabel(x.type))}</span><strong>${x.n}</strong></div>`).join(''):'<div class="empty-panel">No Pokémon added yet.</div>'}</div></section></div></div>`;$('#clearTeam').onclick=()=>{team.length=0;saveAll();renderTeam();};$$('.remove-team').forEach(b=>b.onclick=()=>{toggleTeam(b.dataset.id);renderTeam();});$$('.team-slot.empty').forEach(b=>b.onclick=()=>openTeamPicker());}
function openTeamPicker(){const overlay=document.createElement('div');overlay.className='picker-overlay';overlay.innerHTML=`<div class="picker"><button class="info-close picker-close">×</button><h2>${T('team')}</h2><input class="picker-search" placeholder="${T('search')}"><div class="picker-list"></div></div>`;document.body.appendChild(overlay);const list=overlay.querySelector('.picker-list'),input=overlay.querySelector('.picker-search');const draw=()=>{const q=norm(input.value);const pool=entries.filter(e=>!team.includes(e.id)&&(!q||norm(`${e.name} ${e.form}`).includes(q))).slice(0,80);list.innerHTML=pool.map(e=>`<button class="picker-item" data-id="${esc(e.id)}"><img src="${spritePath(e)}"><span><b>${esc(e.name)}</b><small>${entryTypes(e).map(typeLabel).join(' / ')}</small></span></button>`).join('')||`<div class="empty-panel">${T('noResults')}</div>`;list.querySelectorAll('.picker-item').forEach(b=>b.onclick=()=>{toggleTeam(b.dataset.id);overlay.remove();renderTeam();});};input.oninput=draw;overlay.querySelector('.picker-close').onclick=()=>overlay.remove();overlay.onclick=e=>{if(e.target===overlay)overlay.remove();};draw();input.focus();}
function renderTypeKnowledge(){
  const selected=[...(window.knowledgeTypes||[])];
  const q=window.knowledgeQuery||'';
  const shown=TYPES.filter(t=>!q||norm(typeLabel(t)).includes(norm(q))).slice(0,20);
  const defTypes=selected.length?selected:['Fire'];
  const attackRows=TYPES.map(t=>({type:t,m:effectiveness(defTypes,t)}));
  const groups={strong:attackRows.filter(x=>x.m>1),resist:attackRows.filter(x=>x.m>0&&x.m<1),immune:attackRows.filter(x=>x.m===0),neutral:attackRows.filter(x=>x.m===1)};
  const defensive=(mode)=>TYPES.map(t=>({type:t,m:effectiveness(defTypes,t)}));
  const chips=(arr)=>arr.map(x=>`<span class="knowledge-chip" style="${typeStyle(x.type)}">${esc(typeLabel(x.type))}<small>${x.m===0?'×0':x.m>=4?`${x.m}×`:x.m>1?'×2':x.m<1?'×½':'×1'}</small></span>`).join('')||'<span class="muted-dash">None</span>';
  const comboLabel=defTypes.map(typeLabel).join(' / ');
  const selectedChips=selected.map(t=>`<button class="knowledge-selected" data-remove-type="${esc(t)}" style="${typeStyle(t)}">${esc(typeLabel(t))} ×</button>`).join('');
  const picker=shown.map(t=>`<button class="knowledge-option ${selected.includes(t)?'selected':''}" data-add-type="${esc(t)}" style="${typeStyle(t)}">${esc(typeLabel(t))}</button>`).join('');
  const weak=TYPES.map(t=>({type:t,m:effectiveness(defTypes,t)})).filter(x=>x.m>1);
  const resist=TYPES.map(t=>({type:t,m:effectiveness(defTypes,t)})).filter(x=>x.m>0&&x.m<1);
  const immune=TYPES.map(t=>({type:t,m:effectiveness(defTypes,t)})).filter(x=>x.m===0);
  $('#view').innerHTML=`<div class="page-card knowledge-page"><div class="page-title"><div><div class="eyebrow">TYPE DATABASE</div><h2>Type Information</h2><p>Select one or two defending types to study exact matchups.</p></div><button id="startTypeQuiz" class="primary quiz-launch">Start Quiz</button></div>
  <div class="knowledge-selector"><div class="knowledge-search"><span>⌕</span><input id="knowledgeSearch" value="${esc(q)}" placeholder="Search types..."></div><div class="knowledge-selected-row">${selectedChips||'<span class="selector-hint">Select up to two types</span>'}</div><div class="knowledge-options">${picker}</div></div>
  <div class="knowledge-hero">${defTypes.map(t=>`<span class="big-type" style="${typeStyle(t)}">${esc(typeLabel(t))}</span>`).join('<span class="combo-slash">/</span>')}<div><span class="eyebrow">DEFENSIVE PROFILE</span><h3>${esc(comboLabel)}</h3><p>How each attacking type interacts with this ${selected.length>1?'dual-type':'type'} combination.</p></div></div>
  <div class="knowledge-columns"><section class="knowledge-panel offensive"><div class="panel-heading"><div><span class="eyebrow">ATTACKING</span><h3>Super effective</h3></div></div><div class="chip-cloud">${chips(weak)}</div><div class="knowledge-sub"><h4>Not very effective</h4><div class="chip-cloud">${chips(resist)}</div></div><div class="knowledge-sub"><h4>No effect</h4><div class="chip-cloud">${chips(immune)}</div></div></section><section class="knowledge-panel defensive"><div class="panel-heading"><div><span class="eyebrow">MULTIPLIERS</span><h3>Full matchup</h3></div></div><div class="type-multiplier-grid">${attackRows.map(x=>`<div class="type-multiplier"><span class="knowledge-chip mini" style="${typeStyle(x.type)}">${esc(typeLabel(x.type))}</span><strong class="mult-${x.m===0?'zero':x.m>1?'up':x.m<1?'down':'one'}">${x.m===0?'×0':x.m===1?'×1':x.m+'×'}</strong></div>`).join('')}</div></section></div></div>`;
  $('#knowledgeSearch').oninput=e=>{window.knowledgeQuery=e.target.value;renderTypeKnowledge();};
  $$('[data-add-type]').forEach(b=>b.onclick=()=>{const t=b.dataset.addType;if(selected.includes(t))window.knowledgeTypes=selected.filter(x=>x!==t);else if(selected.length<2)window.knowledgeTypes=[...selected,t];renderTypeKnowledge();});
  $$('[data-remove-type]').forEach(b=>b.onclick=()=>{window.knowledgeTypes=selected.filter(x=>x!==b.dataset.removeType);renderTypeKnowledge();});
  $('#startTypeQuiz').onclick=()=>openTypeQuiz();
}
function randomQuizQuestion(){
  const pool=entries.filter(e=>entryTypes(e).length>=1).slice();
  const e=pool[Math.floor(Math.random()*pool.length)];
  const def=entryTypes(e);
  const correct=TYPES.filter(t=>effectiveness(def,t)>1);
  const choices=[...correct.slice(0,2)];
  while(choices.length<4){const t=TYPES[Math.floor(Math.random()*TYPES.length)];if(!choices.includes(t))choices.push(t);}
  choices.sort(()=>Math.random()-.5);
  return {e,def,correct,choices};
}
function openTypeQuiz(){
  let score=0,streak=0,answered=false,q=randomQuizQuestion();
  const overlay=document.createElement('div');overlay.className='picker-overlay quiz-overlay';
  overlay.innerHTML=`<div class="quiz-modal"><button class="info-close quiz-close">×</button><div class="eyebrow">TYPE TRAINING</div><h2>Type Quiz</h2><div class="quiz-score"><span>Score <b class="quiz-score-value">0</b></span><span>Streak <b class="quiz-streak-value">0</b></span></div><div class="quiz-question"></div><div class="quiz-feedback"></div><button class="primary quiz-next" hidden>Next Question</button></div>`;
  document.body.appendChild(overlay);
  const draw=()=>{answered=false;q=randomQuizQuestion();const qEl=overlay.querySelector('.quiz-question');qEl.innerHTML=`<div class="quiz-prompt">Which attacking type is <b>super effective</b> against:</div><div class="quiz-target">${esc(q.e.name)}<div>${q.def.map(t=>`<span class="type" style="${typeStyle(t)}">${esc(typeLabel(t))}</span>`).join('')}</div></div><div class="quiz-choices">${q.choices.map(t=>`<button class="quiz-choice" data-answer="${esc(t)}" style="${typeStyle(t)}">${esc(typeLabel(t))}</button>`).join('')}</div>`;overlay.querySelector('.quiz-feedback').textContent='';overlay.querySelector('.quiz-next').hidden=true;overlay.querySelectorAll('.quiz-choice').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const ok=q.correct.includes(b.dataset.answer);if(ok){score++;streak++;b.classList.add('correct');}else{streak=0;b.classList.add('wrong');overlay.querySelectorAll('.quiz-choice').forEach(x=>{if(q.correct.includes(x.dataset.answer))x.classList.add('correct');});}overlay.querySelector('.quiz-score-value').textContent=score;overlay.querySelector('.quiz-streak-value').textContent=streak;overlay.querySelector('.quiz-feedback').textContent=ok?`${assistantName()}: Correct, ${greetingName()}!`:`${assistantName()}: Not quite. ${q.correct.map(typeLabel).join(' / ')} is super effective.`;overlay.querySelector('.quiz-next').hidden=false;});};
  overlay.querySelector('.quiz-close').onclick=()=>overlay.remove();overlay.onclick=e=>{if(e.target===overlay)overlay.remove();};overlay.querySelector('.quiz-next').onclick=draw;draw();
}

function renderEvolutionExplorer(){const roots=entries.filter(e=>!speciesForEntry(e)?.preEvolution).filter(e=>!e.form).sort(sortEntry);const q=norm(window.evoQuery||'');const pool=roots.filter(e=>!q||norm(e.name).includes(q)).slice(0,100);$('#view').innerHTML=`<div class="page-card"><div class="page-title"><div><h2>${T('evoExplorer')}</h2><p>${language==='nl'?'Zoek een evolutielijn en bekijk alle vertakkingen.':'Search an evolution line and explore every branch.'}</p></div><input id="evoSearch" class="page-search" value="${esc(window.evoQuery||'')}" placeholder="${T('search')}"></div><div class="explorer-list">${pool.map(e=>`<button class="explorer-row" data-evo="${esc(e.id)}"><img src="${spritePath(e)}"><span><b>${esc(e.name)}</b><small>#${e.dex}</small></span></button>`).join('')||`<div class="empty-panel">${T('noResults')}</div>`}</div></div>`;$('#evoSearch').oninput=e=>{window.evoQuery=e.target.value;renderEvolutionExplorer();};$$('[data-evo]').forEach(b=>b.onclick=()=>openInfo(b.dataset.evo));}
function renderSpawnExplorer(){const q=norm(window.spawnQuery||'');const pool=entries.filter(e=>!q||norm(`${e.name} ${e.form}`).includes(q)).slice(0,100);$('#view').innerHTML=`<div class="page-card"><div class="page-title"><div><h2>${T('spawnExplorer')}</h2><p>${language==='nl'?'Bekijk alle lokale Cobblemon spawngegevens.':'Explore local Cobblemon spawn data.'}</p></div><input id="spawnSearch" class="page-search" value="${esc(window.spawnQuery||'')}" placeholder="${T('search')}"></div><div class="explorer-list">${pool.map(e=>`<button class="explorer-row" data-spawn="${esc(e.id)}"><img src="${spritePath(e)}"><span><b>${esc(e.name)}</b><small>${localSpawn(e).length} spawns</small></span></button>`).join('')}</div></div>`;$('#spawnSearch').oninput=e=>{window.spawnQuery=e.target.value;renderSpawnExplorer();};$$('[data-spawn]').forEach(b=>b.onclick=()=>openInfo(b.dataset.spawn));}
function achievementData(){const main=pageEntries('main');const done=main.filter(e=>state[e.id]).length;const boxes={};for(const e of main){boxes[e.box]??={total:0,done:0};boxes[e.box].total++;if(state[e.id])boxes[e.box].done++;}return[{id:'first',title:language==='nl'?'Eerste vangst':'First catch',desc:language==='nl'?'Verzamel je eerste Pokémon.':'Collect your first Pokémon.',ok:done>=1},{id:'hundred',title:'100 Pokémon',desc:language==='nl'?'Verzamel 100 Pokémon.':'Collect 100 Pokémon.',ok:done>=100},{id:'box',title:language==='nl'?'Box compleet':'Box complete',desc:language==='nl'?'Voltooi een volledige PC-box.':'Complete a full PC box.',ok:Object.values(boxes).some(x=>x.total&&x.done===x.total)},{id:'fire',title:language==='nl'?'Vuurtrainer':'Fire trainer',desc:language==='nl'?'Verzamel 25 Fire Pokémon.':'Collect 25 Fire Pokémon.',ok:main.filter(e=>entryTypes(e).includes('Fire')&&state[e.id]).length>=25},{id:'regional',title:language==='nl'?'Regionale reiziger':'Regional explorer',desc:language==='nl'?'Verzamel 10 regionale vormen.':'Collect 10 regional forms.',ok:main.filter(e=>e.form&&state[e.id]).length>=10},{id:'fav',title:language==='nl'?'Favorietenlijst':'Favorites list',desc:language==='nl'?'Markeer 10 favorieten.':'Mark 10 favorites.',ok:Object.keys(favorites).length>=10},{id:'living',title:'LivingDex Master',desc:language==='nl'?'Voltooi de volledige LivingDex.':'Complete the full LivingDex.',ok:done===main.length}];return{done,total:main.length,list:achievementDataRaw(achievementDataCache)};}
let achievementDataCache=[];function achievementDataRaw(){const main=pageEntries('main');const done=main.filter(e=>state[e.id]).length;const boxes={};for(const e of main){boxes[e.box]??={total:0,done:0};boxes[e.box].total++;if(state[e.id])boxes[e.box].done++;}return[{id:'first',title:language==='nl'?'Eerste vangst':'First catch',desc:language==='nl'?'Verzamel je eerste Pokémon.':'Collect your first Pokémon.',ok:done>=1},{id:'hundred',title:'100 Pokémon',desc:language==='nl'?'Verzamel 100 Pokémon.':'Collect 100 Pokémon.',ok:done>=100},{id:'box',title:language==='nl'?'Box compleet':'Box complete',desc:language==='nl'?'Voltooi een volledige PC-box.':'Complete a full PC box.',ok:Object.values(boxes).some(x=>x.total&&x.done===x.total)},{id:'fire',title:language==='nl'?'Vuurtrainer':'Fire trainer',desc:language==='nl'?'Verzamel 25 Fire Pokémon.':'Collect 25 Fire Pokémon.',ok:main.filter(e=>entryTypes(e).includes('Fire')&&state[e.id]).length>=25},{id:'regional',title:language==='nl'?'Regionale reiziger':'Regional explorer',desc:language==='nl'?'Verzamel 10 regionale vormen.':'Collect 10 regional forms.',ok:main.filter(e=>e.form&&state[e.id]).length>=10},{id:'fav',title:language==='nl'?'Favorietenlijst':'Favorites list',desc:language==='nl'?'Markeer 10 favorieten.':'Mark 10 favorites.',ok:Object.keys(favorites).length>=10},{id:'living',title:'LivingDex Master',desc:language==='nl'?'Voltooi de volledige LivingDex.':'Complete the full LivingDex.',ok:done===main.length}];}
function renderAchievements(){const main=pageEntries('main');const regions=[['Kanto',151],['Johto',100],['Hoenn',135],['Sinnoh',107],['Unova',156],['Kalos',72],['Alola',88],['Galar',89],['Paldea',120]];const special=[['Vivillon', 'vivillon'],['Unown', 'unown'],['Furfrou', 'furfrou'],['Floette', 'floette'],['Minior', 'minior'],['Cobblemon Unique', 'cobblemon-unique'],['Arbok Patterns', 'arbok-patterns'],['Minecraft Forms', 'minecraft-forms'],['Magikarp Jump', 'magikarp-jump']];const regionCards=regions.map(([name,total])=>{const got=new Set(main.filter(e=>e.region===name&&!e.form&&state[e.id]).map(e=>e.dex)).size;const pct=Math.min(100,Math.round(got/total*100));return `<button class="progress-card" data-ach-tab="${name.toLowerCase()}"><div class="progress-card-top"><span>${esc(name)}</span><strong>${got} / ${total}</strong></div><div class="progress-track"><i style="width:${pct}%"></i></div><small>${pct}% complete</small></button>`;}).join('');const specialCards=special.map(([name,id])=>{const list=pageEntries(id);const got=list.filter(e=>state[e.id]).length;const total=list.length;const pct=total?Math.round(got/total*100):0;return `<button class="progress-card special-progress" data-ach-tab="${id}"><div class="progress-card-top"><span>${esc(name)}</span><strong>${got} / ${total}</strong></div><div class="progress-track"><i style="width:${pct}%"></i></div><small>${pct}% complete</small></button>`;}).join('');const done=main.filter(e=>state[e.id]).length;const p=main.length?Math.round(done/main.length*100):0;$('#view').innerHTML=`<div class="page-card achievements-page"><div class="achievement-hero"><div><div class="eyebrow">LIVINGDEX PROGRESS</div><h2>${'Progress'}</h2><p>Track your collection across every region and special collection.</p></div><div class="achievement-total"><strong>${done}</strong><span>/ ${main.length} caught</span><i style="width:${p}%"></i></div></div><section class="achievement-section"><div class="section-heading"><div><span class="eyebrow">REGIONS</span><h3>Regional Pokédex</h3></div><span class="section-note">Complete each region</span></div><div class="progress-grid">${regionCards}</div></section><section class="achievement-section"><div class="section-heading"><div><span class="eyebrow">SPECIAL COLLECTIONS</span><h3>Special Forms</h3></div><span class="section-note">${special.reduce((n,[,id])=>n+pageEntries(id).length,0)} total entries</span></div><div class="progress-grid">${specialCards}</div></section></div>`;$$('[data-ach-tab]').forEach(b=>b.onclick=()=>{const t=b.dataset.achTab;closeInfo();view='dex';tab=t;page=1;query='';selectedTypes=[];$('#search').value='';renderTabs();renderTopNav();render();window.scrollTo({top:0,behavior:'smooth'});});}
function renderDex(){const v=$('#dexView');v.hidden=false;$('#view').hidden=true;render();}
function renderView(){if(view==='dex'){renderDex();return;}$('#dexView').hidden=true;$('#view').hidden=false;if(view==='team')renderTeam();if(view==='types')renderTypeKnowledge();if(view==='achievements')renderAchievements();}
function renderTopNav(){const items=[['dex','LivingDex'],['daily','Daily Dex'],['team','Team Builder'],['types','Type Information'],['training','Training'],['achievements','Progress']];$('#topNav').innerHTML=items.map(([k,n])=>`<button class="top-nav-btn ${view===k?'active':''}" data-view="${k}">${n}</button>`).join('');$$('.top-nav-btn').forEach(b=>b.onclick=()=>{closeInfo();view=b.dataset.view;renderTopNav();renderView();});}
function renderTabs(){const el=$('#tabSelect');const groups=[['LIVINGDEX',[['main','LivingDex']]],['REGIONS',[['kanto','Kanto'],['johto','Johto'],['hoenn','Hoenn'],['sinnoh','Sinnoh'],['unova','Unova'],['kalos','Kalos'],['alola','Alola'],['galar','Galar'],['paldea','Paldea']]],['SPECIAL FORMS',[['vivillon','Vivillon'],['unown','Unown'],['furfrou','Furfrou'],['floette','Floette'],['minior','Minior'],['cobblemon-unique','Cobblemon Unique'],['arbok-patterns','Arbok Patterns'],['minecraft-forms','Minecraft Forms'],['magikarp-jump','Magikarp & Gyarados Jump']]]];el.innerHTML=groups.map(([g,o])=>`<optgroup label="${g}">${o.map(([id,n])=>`<option value="${id}" ${tab===id?'selected':''}>${n}</option>`).join('')}</optgroup>`).join('');} 

function applySettings(){document.documentElement.lang='en';if($('#brandSubtitle'))$('#brandSubtitle').textContent=localStorage.getItem('cobblemon-livingdex-profile')?`Welcome back, ${greetingName()}`:'Personal collection tracker';document.body.classList.toggle('light-mode',theme==='light');$('#search').placeholder='Search Pokémon, form, type or #number...';$('#resetBtn').textContent='Reset Collection';$$('.filter').forEach(b=>b.textContent=({collected:'✓ Caught',favorites:'★ Favorites'})[b.dataset.status]);$('#typesBtn').textContent='Type Filter';$('#settingsTitle').textContent='Settings';$('#settingsThemeLabel').textContent='Theme';} 

function init(){DATA=EMBEDDED_DATA;entries=allEntries();renderTabs();renderTopNav();applySettings();try{renderView();}catch(err){console.error('LivingDex render error:',err);view='dex';renderDex();}if(!profile)showProfileSetup();else showWelcomeBack();}
function populateProfileForm(p={}){
  const trainer=p.trainerName||'';
  const assistant=p.assistantName||'Dex';
  $('#trainerName').value=trainer;
  $('#assistantName').value=assistant;
  const pokemonSelect=$('#favoritePokemon');
  if(pokemonSelect){
    const seen=new Set();
    const mons=pageEntries('main').filter(e=>!e.form&&e.name&&!seen.has(e.name)&&seen.add(e.name));
    pokemonSelect.innerHTML='<option value="">Choose a Pokémon</option>'+mons.map(e=>`<option value="${esc(e.name)}">${esc(e.name)}</option>`).join('');
    pokemonSelect.value=p.favoritePokemon||'';
  }
  const typeSelect=$('#favoriteType');
  if(typeSelect){typeSelect.innerHTML='<option value="">Choose a type</option>'+TYPES.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');typeSelect.value=p.favoriteType||'';}
  if($('#favoriteRegion'))$('#favoriteRegion').value=p.favoriteRegion||'';
  if($('#favoriteGeneration'))$('#favoriteGeneration').value=p.favoriteGeneration||'';
}
function showProfileSetup(){const modal=$('#profileModal');$('#profileGreeting').textContent='Before we begin...';$('#profileIntro').textContent='Tell me a little about yourself. You can change these answers whenever you want.';populateProfileForm(JSON.parse(localStorage.getItem('cobblemon-livingdex-profile')||'{}'));$('#profileContinue').textContent='Start LivingDex';$('#profileOverlay').hidden=false;modal.hidden=false;document.body.classList.add('modal-open');$('#trainerName').focus();}
function openProfileOptions(){const p=JSON.parse(localStorage.getItem('cobblemon-livingdex-profile')||'{}');$('#profileGreeting').textContent='Profile Options';$('#profileIntro').textContent='Update your display name, Dex name and personal preferences.';populateProfileForm(p);$('#profileContinue').textContent='Save Profile';$('#profileOverlay').hidden=false;$('#profileModal').hidden=false;document.body.classList.add('modal-open');$('#settingsMenu').classList.remove('open');$('#trainerName').focus();}

function showWelcomeBack(){const modal=$('#welcomeBackModal'),overlay=$('#welcomeOverlay');if(!modal||!overlay)return;const main=pageEntries('main');const done=main.filter(e=>state[e.id]).length;const pct=main.length?Math.round(done/main.length*100):0;$('#welcomeBackTitle').textContent=`Welcome back, ${greetingName()}!`;$('#welcomeBackText').textContent=`${assistantName()} is ready. Your LivingDex is ${pct}% complete with ${done} of ${main.length} Pokémon caught.`;$('#welcomeProgressText').textContent=pct+'%';$('#welcomeProgressBar').style.width=pct+'%';overlay.hidden=false;modal.hidden=false;document.body.classList.add('modal-open');}
function closeWelcomeBack(){const modal=$('#welcomeBackModal'),overlay=$('#welcomeOverlay');if(!modal||!overlay)return;overlay.hidden=true;modal.hidden=true;document.body.classList.remove('modal-open');}

function closeProfileSetup(){const trainer=($('#trainerName').value||'Trainer').trim()||'Trainer';const assistant=($('#assistantName').value||'Dex').trim()||'Dex';const previous=JSON.parse(localStorage.getItem('cobblemon-livingdex-profile')||'{}');saveProfile({trainerName:trainer,assistantName:assistant,favoritePokemon:$('#favoritePokemon')?.value||'',favoriteType:$('#favoriteType')?.value||'',favoriteRegion:$('#favoriteRegion')?.value||'',favoriteGeneration:$('#favoriteGeneration')?.value||'',showInPlayers:previous.showInPlayers,showOnLeaderboard:previous.showOnLeaderboard,showTeam:previous.showTeam});Object.assign(window,{profileReady:true});if($('#brandSubtitle'))$('#brandSubtitle').textContent=`Welcome back, ${trainer}`;$('#profileOverlay').hidden=true;$('#profileModal').hidden=true;document.body.classList.remove('modal-open');window.LivingDexOnline?.sync?.();renderView();} 

window.openProfileOptions=openProfileOptions;window.state=state;window.favorites=favorites;window.notes=notes;window.team=team;window.saveAll=saveAll;window.saveProfile=saveProfile;window.entryById=entryById;window.spritePath=spritePath;window.render=render;window.__getLivingDexEntries=()=>entries;
$('#tabSelect').onchange=e=>{closeInfo();tab=e.target.value;page=1;query='';selectedTypes=[];status='all';$('#search').value='';$$('.filter').forEach(x=>x.classList.remove('active'));renderTabs();render();};$('#search').oninput=e=>{closeInfo();query=e.target.value;page=1;render();};$$('.filter').forEach(b=>b.onclick=()=>{status=status===b.dataset.status?'all':b.dataset.status;page=1;$$('.filter').forEach(x=>x.classList.toggle('active',x.dataset.status===status));render();});$('#prev').onclick=()=>{page--;render();};$('#next').onclick=()=>{page++;render();};$('#resetBtn').onclick=()=>{if(confirm('Clear all collected Pokémon?')){Object.keys(state).forEach(k=>delete state[k]);saveAll();render();}};$('#typesBtn').onclick=()=>{$('#typeOverlay').hidden=false;$('#typeModal').hidden=false;renderTypeModal();};$('#typeOverlay').onclick=()=>{$('#typeModal').hidden=true;$('#typeOverlay').hidden=true;};$('#typeModalClose').onclick=()=>{$('#typeModal').hidden=true;$('#typeOverlay').hidden=true;};$('#settingsBtn').onclick=e=>{e.stopPropagation();$('#settingsMenu').classList.toggle('open');};document.addEventListener('click',e=>{if(!e.target.closest('.settings-wrap'))$('#settingsMenu').classList.remove('open');});$('#settingsTheme').onchange=e=>{theme=e.target.value;localStorage.setItem('livingdex-theme',theme);applySettings();};$('#profileContinue').onclick=closeProfileSetup;$('#profileBtn').onclick=e=>{e.stopPropagation();openProfileOptions();};$('#profileOverlay').onclick=e=>e.stopPropagation();$('#welcomeBackContinue').onclick=closeWelcomeBack;$('#welcomeOverlay').onclick=closeWelcomeBack;$('#infoClose').onclick=closeInfo;$('#infoOverlay').onclick=closeInfo;document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeInfo();$('#typeModal').hidden=true;$('#typeOverlay').hidden=true;document.querySelector('.picker-overlay')?.remove();}});init();
